/// <summary>
/// The <c>AVAReportFinishedBasketController</c> class is the controller class for <c>Creating contact persons based on GAB</c>
/// </summary>
class AVAReportFinishedBasketController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super(classStr(AVAReportFinishedBasketService), methodStr(AVAReportFinishedBasketService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// construct method of class
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode, default SysOperationExecutionMode::Synchronous</param>
/// <returns>AVAReportFinishedBasketController</returns>
public static AVAReportFinishedBasketController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAReportFinishedBasketController controller;
    controller = new AVAReportFinishedBasketController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    ProdTable   prodTable = _args.record();
    AVAReportFinishedBasketController controller;
    AVAReportFinishedBasketContract   contract;
    controller = AVAReportFinishedBasketController::construct();
    contract = controller.getDataContractObject();
    contract.parmProdId(prodTable.ProdId);
    contract.parmItemId(prodTable.ItemId);
    controller.parmArgs(_args);
    controller.startOperation();
}
